// create_patient - Crea un nuevo paciente
// Puede recibir parámetros directos O leerlos del contexto

const session_id = $('WhatsApp Trigger').item.json.contacts[0].wa_id;
const POSTGREST_URL = 'http://postgrest:3000';
const api_base_url = $('ApiBaseURL').item.json.path;

let patient_name = query.patient_name;
let patient_identifier = query.patient_identifier;
let patient_phone = '+' + session_id;
let patient_email = query.patient_email || null;
let patient_id_type = query.patient_id_type;
let patient_dob = query.patient_dob || null;
let patient_gender = query.patient_gender || null;
let id_document_base64 = query.id_document_base64;

// SIEMPRE leer del contexto para obtener todos los datos, incluyendo la imagen
// Esto es especialmente importante cuando viene del OCR
try {
  const contextResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: `${POSTGREST_URL}/whatsapp_appointment_context?session_id=eq.${session_id}`,
    headers: {
      'Content-Type': 'application/json'
    },
    json: true
  });

  if (contextResponse.length > 0) {
    const ctx = contextResponse[0];
    // Usar valores del contexto si no vienen en el query
    patient_name = patient_name || ctx.patient_name;
    patient_identifier = patient_identifier || ctx.patient_identification;
    patient_phone = patient_phone || ctx.patient_phone;
    patient_email = patient_email || ctx.patient_email;
    patient_id_type = patient_id_type || ctx.patient_id_type;
    patient_dob = patient_dob || ctx.patient_dob;
    patient_gender = patient_gender || ctx.patient_gender;

    // IMPORTANTE: Siempre intentar obtener la imagen del contexto
    if (!id_document_base64 && ctx.id_document_base64) {
      id_document_base64 = ctx.id_document_base64;
    }
  }
} catch (e) {
  // Si falla, continuar con lo que tengamos
}

// Validar que tenemos los datos REQUERIDOS
if (!patient_name || !patient_identifier || !patient_phone || !patient_id_type) {
  return JSON.stringify({ 
    success: false,
    error: 'Faltan parámetros requeridos',
    details: 'Se requieren: patient_name, patient_identifier, patient_phone, patient_id_type',
    received: {
      patient_name: patient_name || 'FALTA',
      patient_identifier: patient_identifier || 'FALTA',
      patient_phone: patient_phone || 'FALTA',
      patient_id_type: patient_id_type || 'FALTA',
      patient_email: patient_email || 'null (opcional)',
      has_document: id_document_base64 ? 'SÍ' : 'NO',
      patient_dob: patient_dob || 'null (opcional)',
      patient_gender: patient_gender || 'null (opcional)',
    },
    hint: 'Usa save_context primero para guardar TODOS los datos del paciente'
  });
}

// Si no hay patient_id_type, usar CC por defecto
if (!patient_id_type) {
  patient_id_type = 'CC';
}

// Formatear teléfono
let formattedPhone = patient_phone;
if (!patient_phone.startsWith('+')) {
  formattedPhone = '+507' + patient_phone;
}

// Crear el paciente en el API
try {
  // Preparar el body
  const requestBody = { 
    name: patient_name, 
    identifier: patient_identifier,
    identification_type: patient_id_type,
    phone: formattedPhone,
    email: patient_email,
    birth_date: patient_dob,
    gender : patient_gender,
  };

  // Agregar el documento si existe
  if (id_document_base64) {
    requestBody.id_document = id_document_base64;
  }

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${api_base_url}patients`,
    headers: { 
      'Authorization': 'Bearer mdt_COcJdos0iGnX1gazI9ouO2GK7NJ26a8OQlPSvhRsajOGlPtpH1xfQlc8Bh6H', 
      'Content-Type': 'application/json',
      'Agent':'SAMI'
    },
    body: requestBody,
    json: true
  });

  // Extraer patient_id del response
  const patient_id = response.id || response.data?.id || null;

  return JSON.stringify({ 
    success: true, 
    patient_id: patient_id,
    patient_name: patient_name,
    patient_identifier: patient_identifier,
    patient_id_type: patient_id_type,
    patient_phone: patient_phone,
    patient_email: patient_email,
    patient_dob: patient_dob,
    patient_gender: patient_gender,
    document_sent: id_document_base64 ? 'YES' : 'NO',
    message: '✅ Paciente creado exitosamente'
  });

} catch (error) {
  // CAPTURAR ERROR COMPLETO DEL API
  let errorDetails = {
    message: error.message,
    status: error.response?.status || 'unknown',
    statusText: error.response?.statusText || 'unknown'
  };

  // Intentar extraer el mensaje de error del API
  if (error.response?.data) {
    errorDetails.api_response = error.response.data;
  }

  return JSON.stringify({ 
    success: false,
    error: error.message,
    details: 'Error al crear el paciente en el API',
    error_info: errorDetails,
    request_sent: {
      name: patient_name,
      identifier: patient_identifier,
      identification_type: patient_id_type,
      phone: patient_phone,
      email: patient_email,
      birth_date: patient_dob,
      gender: patient_gender,
      had_document: id_document_base64 ? 'YES' : 'NO'
    }
  });
}

