// Obtener session_id directamente del nodo Edit Fields
const session_id = $('Edit Fields').item.json.sessionId;
const POSTGREST_URL = 'http://postgrest:3000';
const api_base_url = $('ApiBaseURL').item.json.path;
// Primero intentar obtener del query
let patient_id = query.patient_id;
let practitioner_id = query.practitioner_id;
let consulting_room_id = query.consulting_room_id;
let medical_speciality_id = query.medical_speciality_id;
let date = query.date;
let time = query.time;
let speciality_name = query.speciality_name;

// Si faltan parámetros, obtener del contexto en PostgREST
if (!patient_id || !practitioner_id || !consulting_room_id || !date || !time || !medical_speciality_id) {
    try {
        const response = await this.helpers.httpRequest({
            method: 'GET',
            url: `${POSTGREST_URL}/whatsapp_appointment_context?session_id=eq.${session_id}`,
            headers: {
                'Content-Type': 'application/json'
            },
            json: true
        });

        if (response.length > 0) {
            const ctx = response[0];
            patient_id = patient_id || ctx.patient_id;
            practitioner_id = practitioner_id || ctx.practitioner_id;
            consulting_room_id = consulting_room_id || ctx.consulting_room_id;
            medical_speciality_id = medical_speciality_id || ctx.speciality_id;
            date = date || ctx.date;
            time = time || ctx.time;
            speciality_name = speciality_name || ctx.speciality_name;
        }
    } 
    catch (e) {
        return JSON.stringify({ 
            error: 'Error al acceder al contexto',
            details: e.message
        });
    }
}

// Validar que tenemos todos los datos
if (!patient_id || !practitioner_id || !consulting_room_id || !date || !time || !medical_speciality_id) { 
  return JSON.stringify({ 
    error: 'Faltan parámetros requeridos para crear la cita',
    received: { patient_id, practitioner_id, consulting_room_id, medical_speciality_id, date, time }
  }); 
}

// Convertir fecha de DD-MM-YYYY a YYYY-MM-DD
let formattedDate = date;
if (date.includes('-')) {
    const parts = date.split('-');
    if (parts.length === 3 && parts[0].length === 2) {
        formattedDate = `${parts[2]}-${parts[1]}-${parts[0]}`;
    }
}

// Convertir hora de "10:30 AM" a "10:30:00" (formato 24 horas)
let formattedTime = time;
if (time.includes('AM') || time.includes('PM')) {
    const timeParts = time.replace('AM', '').replace('PM', '').trim().split(':');
    let hours = parseInt(timeParts[0]);
    const minutes = timeParts[1] || '00';

    if (time.includes('PM') && hours !== 12) {
        hours += 12;
    } else if (time.includes('AM') && hours === 12) {
        hours = 0;
    }

    formattedTime = `${hours.toString().padStart(2, '0')}:${minutes}:00`;
} else if (!time.includes(':00')) {
    formattedTime = `${time}:00`;
}

// Combinar fecha y hora
const startDateTime = `${formattedDate} ${formattedTime}`;

try { 
  // ========== CREAR CITA EN API PRINCIPAL ==========
  const response = await this.helpers.httpRequest({ 
    method: 'POST', 
    url: `${api_base_url}appointments`, 
    headers: { 
      'Authorization': 'Bearer mdt_COcJdos0iGnX1gazI9ouO2GK7NJ26a8OQlPSvhRsajOGlPtpH1xfQlc8Bh6H', 
      'Content-Type': 'application/json',
      'Agent':'SAMI'
    }, 
    body: { 
      patient_id: parseInt(patient_id), 
      practitioner_id: parseInt(practitioner_id), 
      medical_speciality_id: parseInt(medical_speciality_id),
      consulting_room_id: parseInt(consulting_room_id), 
      start: startDateTime,
      minutes_duration: 30,
      description: 'Consulta general',
      service_type: speciality_name || 'Consulta médica'
    }, 
    json: true 
  }); 

    // ========== GUARDAR EN BILLING (TRACKING) ==========
    try {
      // Obtener nombre del médico del contexto
      let practitioner_name = 'N/A';
      try {
        const contextResponse = await this.helpers.httpRequest({
          method: 'GET',
          url: `${POSTGREST_URL}/whatsapp_appointment_context?session_id=eq.${session_id}`,
          headers: { 'Content-Type': 'application/json' },
          json: true
        });
        if (contextResponse.length > 0) {
          practitioner_name = contextResponse[0].practitioner_name || 'N/A';
        }
      } catch (e) {
        console.log('No se pudo obtener nombre del médico:', e.message);
      }

      // Calcular mes de facturación (YYYY-MM)
      const mesFacturacion = new Date().toISOString().slice(0, 7);
      const today = new Date().toISOString().slice(0, 13); // YYYY-MM-DDTHH
      const conversation_id = `${session_id}_${today}`;

      // 1️⃣ Insertar en tabla de billing_appointments
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${POSTGREST_URL}/billing_appointments`,
        headers: {
          'Content-Type': 'application/json',
          'Prefer': 'return=representation'
        },
        body: {
          appointment_id: response.data.id?.toString() || `temp_${Date.now()}`,
          medico_id: practitioner_id.toString(),
          medico_nombre: practitioner_name,
          especialidad: speciality_name || 'N/A',
          paciente_phone: session_id,
          fecha_cita: startDateTime,
          mes_facturacion: mesFacturacion,
          facturado: false
        },
        json: true
      });

      console.log('✅ Datos de billing_appointments guardados');

      // 2️⃣ Actualizar billing_conversations
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: `${POSTGREST_URL}/billing_conversations?conversation_id=eq.${conversation_id}`,
        headers: {
          'Content-Type': 'application/json',
          'Prefer': 'return=representation'
        },
        body: {
          fin: new Date().toISOString(),
          cita_agendada: true
        },
        json: true
      });

      console.log('✅ Conversación actualizada (cita_agendada=true, fin registrado)');

    } 
    catch (billingError) {
      // No fallar la creación de cita si falla el billing
      console.error('⚠️ Error en proceso de billing:', billingError.message);
    }

  return JSON.stringify({ 
    success: true, 
    appointment: response,
    message: '✅ Cita creada exitosamente'
  }); 

} 
catch(error) { 
  return JSON.stringify({ 
    error: error.message,
    request_data: {
      patient_id: parseInt(patient_id),
      practitioner_id: parseInt(practitioner_id),
      medical_speciality_id: parseInt(medical_speciality_id),
      consulting_room_id: parseInt(consulting_room_id),
      start: startDateTime,
      minutes_duration: 30,
      description: 'Consulta general',
      service_type: speciality_name || 'Consulta médica'
    }
  }); 
}

