// get_patient - Busca un paciente por cédula

const patient_identification = query.patient_identification;
 const api_base_url = $('ApiBaseURL').item.json.path;

if (!patient_identification) {
  return JSON.stringify({ 
    error: 'Parámetro patient_identification es requerido'
  });
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${api_base_url}patients?search=${encodeURIComponent(patient_identification)}`,
    headers: {
      'Authorization': 'Bearer mdt_COcJdos0iGnX1gazI9ouO2GK7NJ26a8OQlPSvhRsajOGlPtpH1xfQlc8Bh6H',
      'Content-Type': 'application/json',
      'Agent':'SAMI',
    },
    json: true
  });

  // Extraer el array de pacientes
  const patientsArray = response.data || [];
  const count = patientsArray.length;

  if (count === 0) {
    // No se encontró el paciente
    return JSON.stringify({
      success: true,
      found: false,
      patient: null,
      message: 'Paciente no encontrado'
    });
  }

  // Paciente encontrado - tomar el primero
  const patient = patientsArray[0];

  return JSON.stringify({
    success: true,
    found: true,
    patient: {
      id: patient.id,
      name: patient.name,
      identifier: patient.identifier,
      phone: patient.phone,
      email: patient.email || null
    }
  });

} catch (error) {
  return JSON.stringify({
    success: false,
    error: error.message
  });
}

