    if (context_data.speciality_id !== undefined) currentContext.speciality_id = context_data.speciality_id;
    if (context_data.speciality_name !== undefined) currentContext.speciality_name = context_data.speciality_name;
    if (context_data.practitioner_id !== undefined) currentContext.practitioner_id = context_data.practitioner_id;
    if (context_data.practitioner_name !== undefined) currentContext.practitioner_name = context_data.practitioner_name;
    if (context_data.date !== undefined) currentContext.date = context_data.date;
    if (context_data.time !== undefined) currentContext.time = context_data.time;
    if (context_data.consulting_room_id !== undefined) currentContext.consulting_room_id = context_data.consulting_room_id;

    currentContext.session_id = session_id;
    currentContext.updated_at = new Date().toISOString();

    let result;

    if (isUpdate) {
        // ACTUALIZAR registro existente
        result = await this.helpers.httpRequest({
            method: 'PATCH',
            url: `${POSTGREST_URL}/whatsapp_appointment_context?session_id=eq.${session_id}`,
            headers: {
                'Content-Type': 'application/json',
                'Prefer': 'return=representation'
            },
            body: currentContext,
            json: true
        });
    } else {
        // CREAR nuevo registro
        const newContext = {
            session_id: session_id,
            patient_id: currentContext.patient_id || null,
            patient_id_type: currentContext.patient_id_type || null,
            patient_identification: currentContext.patient_identification || null,        
            patient_name: currentContext.patient_name || null,
            patient_phone: currentContext.patient_phone || null,
            patient_email: currentContext.patient_email || null,
            patient_dob: currentContext.patient_birth_date || null,    // NUEVO
            patient_gender: currentContext.patient_gender || null,             // NUEVO
            speciality_id: currentContext.speciality_id || null,
            speciality_name: currentContext.speciality_name || null,
            practitioner_id: currentContext.practitioner_id || null,
            practitioner_name: currentContext.practitioner_name || null,
            date: currentContext.date || null,
            time: currentContext.time || null,
            consulting_room_id: currentContext.consulting_room_id || null,
            updated_at: new Date().toISOString()
        };

        result = await this.helpers.httpRequest({
            method: 'POST',
            url: `${POSTGREST_URL}/whatsapp_appointment_context`,
            headers: {
                'Content-Type': 'application/json',
                'Prefer': 'return=representation'
            },
            body: newContext,
            json: true
        });
    }

    // ⚠️ OMITIR el base64 del resultado
    // Normalizar el resultado (puede ser array o objeto)
    let contextResult = Array.isArray(result) ? result[0] : result;

    // Verificar si existe documento y eliminarlo
    const hasDocument = !!contextResult.id_document_base64;
    if (contextResult.id_document_base64) {
        delete contextResult.id_document_base64;
    }

    // Agregar flag para que el AI sepa que hay documento
    contextResult.has_document = hasDocument;

    return JSON.stringify({
        success: true,
        message: `✅ GUARDADO: ${Object.keys(context_data).join(', ')}`,
        full_context: contextResult,
        operation: isUpdate ? 'UPDATE' : 'INSERT'
    });

} catch (error) {
    let errorDetail = {
        message: error.message,
        session_id: session_id,
        status: error.response?.status,
        statusText: error.response?.statusText
    };

    if (error.response?.data) {
        errorDetail.postgres_error = error.response.data;
    }

    return JSON.stringify({
        success: false,
        error: error.message,
        details: 'Error al guardar en PostgreSQL',
        debug: errorDetail,
        data_sent: context_data
    });
}

