// Convertir fecha de DD-MM-YYYY a YYYY-MM-DD
let formattedDate = new_date;
if (new_date.includes('-')) {
    const parts = new_date.split('-');
    if (parts.length === 3 && parts[0].length === 2) {
        formattedDate = `${parts[2]}-${parts[1]}-${parts[0]}`;
    }
}

// Convertir hora de "10:30 AM" a "10:30:00" (formato 24 horas)
let formattedTime = new_time;
if (new_time.includes('AM') || new_time.includes('PM')) {
    const timeParts = new_time.replace('AM', '').replace('PM', '').trim().split(':');
    let hours = parseInt(timeParts[0]);
    const minutes = timeParts[1] || '00';

    if (new_time.includes('PM') && hours !== 12) {
        hours += 12;
    } else if (new_time.includes('AM') && hours === 12) {
        hours = 0;
    }

    formattedTime = `${hours.toString().padStart(2, '0')}:${minutes}:00`;
} else if (!new_time.includes(':00')) {
    formattedTime = `${new_time}:00`;
}

const startDateTime = `${formattedDate} ${formattedTime}`;

